contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address[] memory tos, uint v) public payable {
        require(tos.length > 0);
        // address(this) has a payable fallback, so every transferFrom sub-call succeeds
        bool r = c.transfer(from, address(this), tos, v);
        assert(r == true);
    }
    fallback() external payable {}
    receive() external payable {}
}

